
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_x_sogga11_x_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_x_sogga11_x", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.531676157864965e+00, -2.481792646880292e+00, -2.411888355314445e+00, -2.315040302935266e+00, -2.183039478341061e+00, -2.007272822310726e+00, -1.780837570150894e+00, -1.502401127691176e+00, -1.181719362682834e+00, -8.416121255711512e-01, -5.156992237987899e-01, -4.092407162532173e-01, -3.565792707806294e-01, -2.897333007000967e-01, -2.013600813761058e-01, -1.023562801007768e-01, -2.448091199535297e-03, 8.334787317166000e-05, 3.606382833581846e-06, 3.873982973378742e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


